#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;

vector<long long> allNumbers, allSums;

void findAllSubsets(int index, long long sumSoFar) {
    if (index == (int)allNumbers.size()) {
        allSums.push_back(sumSoFar);
        return;
    }
    findAllSubsets(index + 1, sumSoFar + allNumbers[index]);
    findAllSubsets(index + 1, sumSoFar);
}

bool validate(long long M, long long W, long long x) {
    if (x == M) return true;

    long long total = x + M;
    while (total > 0) {
        if (total % W > 1) return false;
        total /= W;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    stringstream ss(line);
    long long baseW, targetM;
    ss >> baseW >> targetM;

    if (baseW == 2) {
        cout << "YES\n";
        return 0;
    }

    allNumbers.clear();
    allNumbers.push_back(1LL);
    allNumbers.push_back(baseW);

    long long val = baseW;
    const long long limit = (long long)1e10;

    while (true) {
        val *= baseW;
        if (val < 0 || val > limit) break;
        allNumbers.push_back(val);
    }

    allSums.clear();
    findAllSubsets(0, 0);

    bool answer = false;
    for (long long candidate : allSums) {
        answer |= validate(targetM, baseW, candidate);
        if (answer) break;
    }

    cout << (answer ? "YES" : "NO") << "\n";

    return 0;
}
